    description text NOT NULL,
    allowed_roles jsonb,
    conditions jsonb,
    system_action character varying(100),
    metadata jsonb,
    from_state_id uuid NOT NULL,
    to_state_id uuid NOT NULL,
    workflow_id uuid NOT NULL
);


ALTER TABLE public.workflow_engine_transition OWNER TO postgres;

